/* ============================================
   SLIDER COMPONENT
   Range input for selecting values
   ============================================ */

.ds-slider {
  display: flex;
  align-items: center;
  width: 100%;
}

/* ============================================
   INPUT — RESET & BASE
   ============================================ */

.ds-slider__input {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  border-radius: var(--radius-pill);
  outline: none;
  cursor: pointer;
  background: var(--color-bg-container-tertiary);
}

.ds-slider--compact .ds-slider__input {
  height: 4px;
}

/* ============================================
   THUMB — WEBKIT
   ============================================ */

.ds-slider__input::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  border-radius: var(--radius-pill);
  background: var(--color-action-primary-bg);
  border: 2px solid var(--color-action-primary-bg);
  cursor: pointer;
  transition: box-shadow var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-slider--compact .ds-slider__input::-webkit-slider-thumb {
  width: 16px;
  height: 16px;
}

.ds-slider__input::-webkit-slider-thumb:hover {
  box-shadow: 0 0 0 4px var(--color-action-primary-bg-hover);
}

/* ============================================
   THUMB — MOZ
   ============================================ */

.ds-slider__input::-moz-range-thumb {
  width: 20px;
  height: 20px;
  border-radius: var(--radius-pill);
  background: var(--color-action-primary-bg);
  border: 2px solid var(--color-action-primary-bg);
  cursor: pointer;
  transition: box-shadow var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-slider--compact .ds-slider__input::-moz-range-thumb {
  width: 16px;
  height: 16px;
}

.ds-slider__input::-moz-range-thumb:hover {
  box-shadow: 0 0 0 4px var(--color-action-primary-bg-hover);
}

/* ============================================
   DISABLED
   ============================================ */

.ds-slider--disabled {
  opacity: 0.4;
  pointer-events: none;
}

'use client';

import React from 'react';
import './Slider.css';

/** Props owned by Slider itself — everything else falls through to the <input type="range">. */
type SliderOwnProps = {
  /** Current value */
  value?: number;
  /** Minimum value */
  min?: number;
  /** Maximum value */
  max?: number;
  /** Step increment */
  step?: number;
  /** Component size (not the native character-width `size` attribute) */
  size?: 'default' | 'compact';
  /**
   * Convenience callback receiving the numeric value directly.
   * Fires alongside `onChange`, which keeps the standard React event signature
   * so form libraries work unmodified.
   */
  onValueChange?: (value: number) => void;
  /** Additional CSS classes — applied to the wrapper, not the <input> */
  className?: string;
  /**
   * Legacy accessible-name prop.
   *
   * @deprecated Pass the native `aria-label` attribute instead.
   */
  ariaLabel?: string;
};

export interface SliderProps
  extends SliderOwnProps,
    Omit<React.ComponentPropsWithoutRef<'input'>, keyof SliderOwnProps | 'type'> {}

/**
 * Slider allows selecting a value from within a given range.
 *
 * Forwards a ref to the underlying `<input type="range">` and spreads
 * unrecognised props onto it.
 */
export const Slider = React.forwardRef<HTMLInputElement, SliderProps>(
  (
    {
      value = 50,
      min = 0,
      max = 100,
      step = 1,
      disabled = false,
      size = 'default',
      onChange,
      onValueChange,
      ariaLabel = 'Slider',
      className = '',
      style,
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-slider';
    const classes = [
      baseClass,
      `${baseClass}--${size}`,
      disabled ? `${baseClass}--disabled` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const percentage = ((value - min) / (max - min)) * 100;

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      onChange?.(e);
      onValueChange?.(Number(e.target.value));
    };

    return (
      <div className={classes}>
        <input
          {...rest}
          ref={ref}
          type="range"
          className={`${baseClass}__input`}
          value={value}
          min={min}
          max={max}
          step={step}
          disabled={disabled}
          onChange={handleChange}
          aria-label={ariaLabel || rest['aria-label']}
          style={{
            background: `linear-gradient(to right, var(--color-action-primary-bg) ${percentage}%, var(--color-bg-container-tertiary) ${percentage}%)`,
            ...style,
          }}
        />
      </div>
    );
  },
);

Slider.displayName = 'Slider';
